import './user_profile.dart';

/// Holds the result of a compatibility calculation between two profiles.
class ProfileMatchResult implements Comparable<ProfileMatchResult> {
  /// The candidate profile that was evaluated.
  final UserProfile profile;

  /// Overall compatibility score from 0.0 to 1.0 (multiply by 100 for %).
  final double matchScore;

  /// Breakdown of individual dimension scores (0.0 – 1.0 each).
  final double interestsScore;
  final double valuesScore;
  final double neurotypesScore;
  final double communicationScore;

  /// Short insight string generated by Gemini AI (may be empty).
  final String aiInsight;

  /// Short one-liner insight (used in card header area).
  final String shortInsight;

  /// Whether this result was refined by the Gemini AI engine.
  final bool aiRefined;

  /// Distance in km from the current user (null if coordinates unavailable).
  final double? distanceKm;

  /// Connection potential level: "alta", "media", "moderada".
  final String connectionPotential;

  const ProfileMatchResult({
    required this.profile,
    required this.matchScore,
    required this.interestsScore,
    required this.valuesScore,
    required this.neurotypesScore,
    required this.communicationScore,
    this.aiInsight = '',
    this.shortInsight = '',
    this.aiRefined = false,
    this.distanceKm,
    this.connectionPotential = '',
  });

  /// Match percentage as a human-readable integer (0 – 100).
  int get matchPercentage => (matchScore * 100).round().clamp(0, 100);

  /// Serializes to JSON.
  Map<String, dynamic> toJson() => {
    'profile': profile.toJson(),
    'matchScore': matchScore,
    'interestsScore': interestsScore,
    'valuesScore': valuesScore,
    'neurotypesScore': neurotypesScore,
    'communicationScore': communicationScore,
    'aiInsight': aiInsight,
    'shortInsight': shortInsight,
    'aiRefined': aiRefined,
    'distanceKm': distanceKm,
    'connectionPotential': connectionPotential,
  };

  @override
  int compareTo(ProfileMatchResult other) =>
      other.matchScore.compareTo(matchScore);

  @override
  String toString() =>
      'ProfileMatchResult(profile: ${profile.displayName}, matchScore: $matchPercentage%, aiRefined: $aiRefined, distanceKm: $distanceKm)';
}
